using System.Collections;
using UnityEngine;
using UnityEngine.UI;
namespace DiwaliGameplay {
public class FireworksGame : VenueGame {
 public GrabbableItem rocket,fountain,spinner,plunger;
 public Transform rocketSocket,fountainSocket,spinnerSocket,rocketPlatform,lift,spinnerPivot;
 public ParticleSystem rocketEffect,fountainEffect,spinnerEffect;
 public int stage,aimPreset,speedPreset;
 public Slider timingBar;
 public Vector3 panelPosition;public Quaternion panelRotation;
 public Vector3 rocketStagingPosition;
 public bool rocketLoaded,fountainLoaded,spinnerLoaded,raised;
 public float phase,holdProgress;
 public Vector3 liftHome,plungerHome;
 public Transform plungerFrame;
 public Quaternion rocketHome,spinnerHome;
 public Vector3 rocketTiltAxis=Vector3.right,rocketLocalLaunchAxis=Vector3.up;
 public Quaternion rocketWorldHome=Quaternion.identity;
 bool rocketRunning,fountainRunning,spinnerRunning;
 public float travel=.18f;
 public bool TimingReady=>true;
 VenuePanel panel;
 DiyaRestTarget rocketTarget,fountainTarget,spinnerTarget;TextMesh showBoard;
 Button beginButton,finaleButton;
 Slider aimSlider,liftSlider,speedSlider,boardSlider;FireworksTargetBoard targetBoard;bool launching;
 bool rocketHandled,fountainHandled,spinnerHandled,triggerHeld,handBaselineSet,wasDown;
 float handStartY,liftAmount,plungerDepression,spinSpeed=45;
 Quaternion plungerRotation;
 Vector3 rocketStaging;
 protected override void Awake(){base.Awake();if(rocketPlatform&&rocketWorldHome==Quaternion.identity)rocketWorldHome=rocketPlatform.rotation;if(rocket){rocketStaging=rocketStagingPosition!=Vector3.zero?rocketStagingPosition:rocket.transform.position;var delta=Vector3.ProjectOnPlane(rocketStaging-rocketSocket.position,Vector3.up);if(delta.magnitude<.7f){var venue=GameObjectUtility.FindExact("Fireworks - Native PBR");var side=venue?venue.right:Vector3.right;rocketStaging=rocketSocket.position+side*.95f;rocketStaging.y=rocketSocket.position.y;}}if(plunger){plungerFrame=plunger.transform.parent?plunger.transform.parent:transform;plungerHome=plungerFrame.InverseTransformPoint(plunger.transform.position);plungerRotation=plunger.transform.rotation;plunger.grab.trackPosition=false;plunger.grab.trackRotation=false;plunger.grab.trackScale=false;plunger.grab.activated.AddListener(_=>triggerHeld=true);plunger.grab.deactivated.AddListener(_=>triggerHeld=false);plunger.grab.selectEntered.AddListener(e=>{handStartY=e.interactorObject.GetAttachTransform(plunger.grab).position.y;handBaselineSet=true;});plunger.grab.selectExited.AddListener(_=>{triggerHeld=false;handBaselineSet=false;});}}
 void Start(){howToPlay="No timing challenge. Each station has three steps: LOAD, ADJUST, PRESS PLUNGER.\n1. Begin, grip the rocket from its tray, and release it near the support.\n2. Adjust rocket tilt and target board height. Aim at the rings; a hit sends the rocket into the sky. Grab the plunger handle and push it down fully to launch.\n3. Load the fountain, adjust Lift, then grab and press the plunger.\n4. Load the spinner, adjust Speed, then grab and press the plunger.\n5. Select Finale to launch more fireworks around the big central decoration. No other venue is required. All activated fireworks keep running until Restart. The target slides up and down its floor stand.";
  var venue=GameObjectUtility.FindExact("Fireworks - Native PBR");if(venue){var board=GameObjectUtility.FindUnder(venue,"board");if(board){var b=GameObjectUtility.BoundsOf(board);var toward=Vector3.back;float front=Mathf.Abs(toward.x)*b.extents.x+Mathf.Abs(toward.z)*b.extents.z;panelPosition=b.center+toward*(front+.04f);panelRotation=Quaternion.LookRotation(-toward,Vector3.up);}}
  panel=VenuePanel.Create(this,panelPosition,panelRotation,"LOAD / ADJUST / PRESS PLUNGER");panel.SetPhysicalSize(.75f,.8f);panel.autoFacePlayer=false;var recenter=panel.transform.Find("Activity tools/Move menu here");if(recenter)recenter.gameObject.SetActive(false);beginButton=panel.AddButton("Begin Light Show",BeginGame);aimSlider=panel.AddSlider("Tilt rocket up / down",.5f,AdjustAim);liftSlider=panel.AddSlider("Fountain lift height",.25f,AdjustLift);speedSlider=panel.AddSlider("Spinner speed",.25f,AdjustSpeed);foreach(var s in new[]{aimSlider,liftSlider,speedSlider}){s.minValue=0;s.maxValue=1;}finaleButton=panel.AddButton("Finale",Finale);rocket.transform.position=rocketStaging;rocketTarget=DiyaRestTarget.Create(transform,rocketSocket,rocket,1f,()=>begun&&!completed&&stage==0&&!rocketLoaded);fountainTarget=DiyaRestTarget.Create(transform,fountainSocket,fountain,1f,()=>begun&&!completed&&stage==1&&!fountainLoaded);spinnerTarget=DiyaRestTarget.Create(transform,spinnerSocket,spinner,1f,()=>begun&&!completed&&stage==2&&!spinnerLoaded);BuildShowBoard();var placement=gameObject.AddComponent<FireworksMenuPlacement>();placement.owner=this;placement.panel=panel;placement.board=targetBoard.board;foreach(var effect in new[]{rocketEffect,fountainEffect,spinnerEffect})FestivalParticleStyle.Apply(effect);var rocketMain=rocketEffect.main;rocketMain.startLifetime=2;rocketMain.startSpeed=3.8f;var trails=rocketEffect.trails;trails.enabled=true;trails.lifetime=.22f;FireworksEffectPolish.Configure(this);RefreshControls();}
 void BuildShowBoard(){var venue=GameObjectUtility.FindExact("Fireworks - Native PBR");var board=venue?GameObjectUtility.FindUnder(venue,"board"):null;if(!board)return;targetBoard=gameObject.AddComponent<FireworksTargetBoard>();targetBoard.Configure(board,GameObjectUtility.FindUnder(venue,"board stand"));boardSlider=panel.AddSlider("Target board height",.5f,v=>{targetBoard.SetHeight(v);Credit("board-height");status="Adjust rocket tilt toward the target, then push the plunger. A hit sends it into the sky.";});targetBoard.SetHeight(.5f);panelPosition=new Vector3(rocketSocket.position.x-2f,1.5f,rocketSocket.position.z-.35f);panel.transform.SetPositionAndRotation(panelPosition,panelRotation);panel.autoFacePlayer=true;}
 void PlacePanel(){if(panel)panel.transform.SetPositionAndRotation(panelPosition,panelRotation);}
 void RefreshControls(){if(!panel)return;beginButton.gameObject.SetActive(!begun);panel.SetControlVisible(aimSlider,begun&&stage==0&&rocketLoaded);if(boardSlider)panel.SetControlVisible(boardSlider,begun&&stage==0&&rocketLoaded);panel.SetControlVisible(liftSlider,begun&&stage==1&&fountainLoaded);panel.SetControlVisible(speedSlider,begun&&stage==2&&spinnerLoaded);finaleButton.gameObject.SetActive(begun&&stage==3&&!completed);}
 public override void BeginGame(){ResetGame();base.BeginGame();Credit("begin");status="ROCKET 1/3: grip the rocket from the staging tray and release it onto its support.";PlacePanel();}
 public bool Load(GrabbableItem item){if(!begun||completed||item.IsHeld)return false;if(stage==0&&item==rocket&&!rocketLoaded){rocketLoaded=true;rocket.SnapTo(rocketSocket,true);Credit("rocket-load");status="ROCKET 2/3: move the Aim slider. The platform tilts visibly up and down.";}else if(stage==1&&item==fountain&&!fountainLoaded){fountainLoaded=true;fountain.SnapTo(fountainSocket,true);Credit("fountain-load");status="FOUNTAIN 2/3: move the Lift slider to choose a height.";}else if(stage==2&&item==spinner&&!spinnerLoaded){spinnerLoaded=true;spinner.SnapTo(spinnerSocket,true);Credit("spinner-load");status="SPINNER 2/3: move the Speed slider to choose its speed.";}else return false;PlacePanel();RefreshControls();return true;}
 public void AdjustAim(float value){if(!begun||stage!=0||!rocketLoaded)return;aimPreset=1;rocketPlatform.localRotation=rocketPlatform.parent?Quaternion.Inverse(rocketPlatform.parent.rotation)*rocketWorldHome*Quaternion.AngleAxis(-Mathf.Lerp(4,24,value),Quaternion.Inverse(rocketWorldHome)*rocketTiltAxis.normalized):rocketWorldHome*Quaternion.AngleAxis(-Mathf.Lerp(4,24,value),Quaternion.Inverse(rocketWorldHome)*rocketTiltAxis.normalized);Credit("aim");status="Aim at the target rings. Adjust target height if needed, then push the plunger.";RefreshControls();}
 public void AdjustLift(float value){if(!begun||stage!=1||!fountainLoaded)return;raised=true;liftAmount=Mathf.Lerp(.05f,.35f,value);Credit("raise");status="FOUNTAIN 3/3: grab the plunger and push it fully down.";RefreshControls();}
 public void AdjustSpeed(float value){if(!begun||stage!=2||!spinnerLoaded)return;speedPreset=1;spinSpeed=Mathf.Lerp(25,150,value);Credit("spin");status="SPINNER 3/3: grab the plunger and push it fully down.";RefreshControls();}
 public void Aim()=>AdjustAim(.65f);public void Raise()=>AdjustLift(.65f);public void Spin()=>AdjustSpeed(.65f);
 public bool Press(float ignoredTiming){if(launching||!begun||completed||!plunger.IsHeld||!handBaselineSet||plungerDepression<Mathf.Max(.18f,travel))return false;if(stage==0&&rocketLoaded&&aimPreset==1){Credit("plunger-press");launching=true;StartCoroutine(TargetLaunch());status="Rocket launched toward target...";}else if(stage==1&&fountainLoaded&&raised){Credit("plunger-press");holdProgress=2;fountainRunning=true;StartLoop(fountainEffect);stage=2;status="SPINNER 1/3: load the spinner onto its support.";}else if(stage==2&&spinnerLoaded&&speedPreset==1){Credit("plunger-press");spinnerRunning=true;StartLoop(spinnerEffect);stage=3;status="All three displays are ready. Select Finale.";}else{status="Load the current firework and adjust its slider before activating it.";return false;}PlacePanel();RefreshControls();return true;}
 public void Finale(){if(!begun||stage!=3||completed)return;Credit("finale");StartLoop(rocketEffect);StartLoop(fountainEffect);StartLoop(spinnerEffect);Complete("Finale! Fireworks are launching around the central decoration.");RefreshControls();}
 void StartLoop(ParticleSystem effect){if(!effect)return;foreach(var particle in effect.GetComponentsInChildren<ParticleSystem>(true)){var main=particle.main;main.loop=true;}effect.Play(true);}
 void ShowRocket(bool visible){foreach(var renderer in rocket.GetComponentsInChildren<MeshRenderer>(true))renderer.enabled=visible;}
 Vector3 LaunchDirection()=>rocket.transform.TransformDirection(rocketLocalLaunchAxis.sqrMagnitude>.001f?rocketLocalLaunchAxis.normalized:Vector3.up).normalized;
 public bool TargetAligned(){if(!targetBoard)return false;return targetBoard.TryAim(rocketSocket.position,LaunchDirection(),out _);}
 IEnumerator TargetLaunch(){ShowRocket(true);rocket.SnapTo(rocketSocket,true);var start=rocket.transform.position;var direction=LaunchDirection();bool hit=targetBoard&&targetBoard.TryAim(start,direction,out _);Vector3 end=start+direction*3;if(hit)targetBoard.TryAim(start,direction,out end);rocket.transform.SetParent(transform,true);for(float t=0;t<.65f;t+=Time.deltaTime){rocket.transform.position=Vector3.Lerp(start,end,t/.65f);yield return null;}if(!hit){targetBoard.ShowMiss();rocket.SnapTo(rocketSocket,true);launching=false;status="Missed the target. Adjust tilt or target height, then press the plunger again.";yield break;}rocket.transform.position=end;StartCoroutine(targetBoard.Hit(end));var launchRotation=rocket.transform.rotation;var skyRotation=Quaternion.FromToRotation(direction,Vector3.up)*launchRotation;for(float t=0;t<1.2f;t+=Time.deltaTime){rocket.transform.rotation=Quaternion.Slerp(launchRotation,skyRotation,Mathf.Clamp01(t/.3f));rocket.transform.position=end+Vector3.up*(t*6)+Vector3.back*(t*.6f);yield return null;}rocketEffect.transform.position=rocket.transform.position;ShowRocket(false);StartLoop(rocketEffect);rocketRunning=true;stage=1;launching=false;status="Target hit! ROCKET keeps celebrating. Load the fountain onto the lift.";RefreshControls();StartCoroutine(RocketFlight());}
 IEnumerator RocketFlight(){while(rocketRunning){yield return new WaitForSeconds(2);ShowRocket(true);rocket.SnapTo(rocketSocket,true);var start=rocket.transform.position;var direction=LaunchDirection();Vector3 target;if(!targetBoard.TryAim(start,direction,out target))target=start+direction*2;rocket.transform.SetParent(transform,true);var launchRotation=rocket.transform.rotation;var skyRotation=Quaternion.FromToRotation(direction,Vector3.up)*launchRotation;for(float t=0;t<1.6f&&rocketRunning;t+=Time.deltaTime){if(t>.5f)rocket.transform.rotation=Quaternion.Slerp(launchRotation,skyRotation,Mathf.Clamp01((t-.5f)/.3f));rocket.transform.position=t<.5f?Vector3.Lerp(start,target,t/.5f):target+Vector3.up*((t-.5f)*6);yield return null;}rocketEffect.transform.position=rocket.transform.position;ShowRocket(false);StartLoop(rocketEffect);}}
 public override void Tick(){RefreshControls();if(showBoard)showBoard.text="FESTIVAL SHOW\n"+(rocketRunning?"[ON] ROCKET":"[ ] ROCKET")+"\n"+(fountainRunning?"[ON] FOUNTAIN":"[ ] FOUNTAIN")+"\n"+(spinnerRunning?"[ON] SPINNER":"[ ] SPINNER")+"\n"+(stage==3?"READY FOR FINALE":"LOAD  >  ADJUST  >  PLUNGE");if(!begun)return;if(!completed){rocketHandled|=rocket.IsHeld;fountainHandled|=fountain.IsHeld;spinnerHandled|=spinner.IsHeld;if(rocketHandled&&!rocketLoaded&&!rocket.IsHeld&&rocketTarget.CanCapture())Load(rocket);if(fountainHandled&&!fountainLoaded&&!fountain.IsHeld&&fountainTarget.CanCapture())Load(fountain);if(spinnerHandled&&!spinnerLoaded&&!spinner.IsHeld&&spinnerTarget.CanCapture())Load(spinner);}lift.localPosition=Vector3.MoveTowards(lift.localPosition,liftHome+Vector3.up*liftAmount,Time.deltaTime*.5f);if(spinnerRunning)spinnerPivot.Rotate(Vector3.right,spinSpeed*Time.deltaTime,Space.Self);float down=0;if(plunger.IsHeld&&handBaselineSet&&plunger.grab.interactorsSelecting.Count>0){var hand=plunger.grab.interactorsSelecting[0].GetAttachTransform(plunger.grab);down=Mathf.Clamp(handStartY-hand.position.y,0,Mathf.Max(.18f,travel));}plunger.transform.SetPositionAndRotation(plungerFrame.TransformPoint(plungerHome)+Vector3.down*down,plungerRotation);plungerDepression=down;bool pressed=plunger.IsHeld&&down>=Mathf.Max(.18f,travel);if(pressed&&!wasDown)Press(0);wasDown=pressed;}
 public override void ResetGame(){StopAllCoroutines();launching=false;if(targetBoard){targetBoard.StopAllCoroutines();targetBoard.SetHeight(.5f);if(boardSlider)boardSlider.SetValueWithoutNotify(.5f);}rocketRunning=fountainRunning=spinnerRunning=false;base.ResetGame();stage=aimPreset=speedPreset=0;rocketLoaded=fountainLoaded=spinnerLoaded=raised=rocketHandled=fountainHandled=spinnerHandled=triggerHeld=handBaselineSet=wasDown=false;phase=holdProgress=liftAmount=plungerDepression=0;foreach(var item in new[]{rocket,fountain,spinner,plunger})if(item)item.ResetItem();if(rocket){ShowRocket(true);rocket.transform.position=rocketStaging;}if(lift)lift.localPosition=liftHome;if(rocketPlatform)rocketPlatform.rotation=rocketWorldHome;if(spinnerPivot)spinnerPivot.localRotation=spinnerHome;foreach(var p in new[]{rocketEffect,fountainEffect,spinnerEffect})if(p)p.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);PlacePanel();}
}
}
